-- Synthetic SQLite fixture generated by the stores at main c70d957.
PRAGMA foreign_keys=OFF;
CREATE TABLE runs (
  id TEXT PRIMARY KEY,
  state TEXT NOT NULL,
  record TEXT NOT NULL
) STRICT;
CREATE TABLE run_events (
  sequence INTEGER PRIMARY KEY,
  run_id TEXT NOT NULL REFERENCES runs(id),
  at INTEGER NOT NULL,
  state TEXT NOT NULL,
  record TEXT NOT NULL
) STRICT;
CREATE TABLE web_sessions (
  id TEXT PRIMARY KEY,
  upstream_id TEXT NOT NULL UNIQUE,
  agent TEXT NOT NULL CHECK(agent IN ('inspector', 'workbook')),
  alias TEXT NOT NULL,
  created_at INTEGER NOT NULL
) STRICT;
CREATE TABLE attachments (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL REFERENCES web_sessions(id),
  bytes INTEGER NOT NULL CHECK(bytes > 0),
  record TEXT NOT NULL
) STRICT;
CREATE INDEX attachments_by_session ON attachments(session_id);
CREATE TABLE web_turns (
  session_id TEXT NOT NULL REFERENCES web_sessions(id),
  run_id TEXT PRIMARY KEY REFERENCES runs(id),
  request_hash TEXT NOT NULL
) STRICT;
CREATE INDEX web_turns_by_session ON web_turns(session_id);
CREATE TABLE web_session_display (
      id TEXT PRIMARY KEY REFERENCES web_sessions(id),
      title TEXT,
      removed INTEGER NOT NULL DEFAULT 0
    ) STRICT;
CREATE TABLE web_session_project (
      id TEXT PRIMARY KEY REFERENCES web_sessions(id),
      project TEXT NOT NULL
    ) STRICT;
CREATE TABLE web_preferences (
      id INTEGER PRIMARY KEY CHECK(id = 1),
      name TEXT NOT NULL,
      introduction TEXT NOT NULL,
      instructions TEXT NOT NULL
    ) STRICT;
CREATE TABLE web_settings_audit (
      id INTEGER PRIMARY KEY,
      section TEXT NOT NULL,
      changed_at INTEGER NOT NULL
    ) STRICT;
CREATE TABLE web_turn_limits (
      id INTEGER PRIMARY KEY CHECK(id = 1),
      settings TEXT NOT NULL
    ) STRICT;
CREATE TABLE web_model_settings (
      id INTEGER PRIMARY KEY CHECK(id = 1),
      alias TEXT NOT NULL
    ) STRICT;
CREATE TABLE web_model_catalog (
      id INTEGER PRIMARY KEY CHECK(id = 1),
      ids TEXT NOT NULL,
      discovered_at INTEGER NOT NULL
    ) STRICT;
CREATE TABLE web_model_selection (
      id INTEGER PRIMARY KEY CHECK(id = 1),
      ids TEXT NOT NULL
    ) STRICT;
CREATE TABLE web_project_folders (
      project TEXT NOT NULL,
      folder TEXT NOT NULL,
      PRIMARY KEY(project, folder)
    ) STRICT;
CREATE TABLE web_action_decisions (
      id INTEGER PRIMARY KEY,
      session_id TEXT NOT NULL REFERENCES web_sessions(id),
      action TEXT NOT NULL,
      decision TEXT NOT NULL,
      created_at INTEGER NOT NULL
    ) STRICT;
CREATE TABLE web_message_annotations (
      session_id TEXT NOT NULL REFERENCES web_sessions(id),
      message_id TEXT NOT NULL,
      note TEXT,
      rating TEXT,
      reason TEXT,
      PRIMARY KEY(session_id, message_id)
    ) STRICT;
CREATE TABLE web_turn_replies (
      run_id TEXT PRIMARY KEY REFERENCES runs(id),
      message_id TEXT NOT NULL,
      text TEXT NOT NULL
    ) STRICT;
CREATE TABLE web_session_knowledge_disabled (
      id TEXT PRIMARY KEY REFERENCES web_sessions(id)
    ) STRICT;
CREATE TABLE web_knowledge_settings (
      id INTEGER PRIMARY KEY CHECK(id = 1),
      atlas_url TEXT NOT NULL,
      toolbox INTEGER NOT NULL CHECK(toolbox IN (0, 1))
    ) STRICT;
CREATE TABLE mcp_servers (
      id TEXT PRIMARY KEY NOT NULL,
      definition TEXT NOT NULL,
      created_at INTEGER NOT NULL,
      updated_at INTEGER NOT NULL
    ) STRICT;
CREATE TABLE web_appearance (
      id INTEGER PRIMARY KEY CHECK(id = 1),
      theme TEXT NOT NULL,
      density TEXT NOT NULL,
      avatar BLOB,
      mime TEXT
    ) STRICT;
CREATE TABLE agents (
  id TEXT PRIMARY KEY,
  role TEXT NOT NULL CHECK(role IN ('orchestrator', 'specialist')),
  builtin_key TEXT UNIQUE,
  state TEXT NOT NULL CHECK(state IN ('active', 'archived')),
  name TEXT NOT NULL CHECK(length(name) <= 80),
  introduction TEXT NOT NULL CHECK(length(introduction) <= 500),
  instructions TEXT NOT NULL CHECK(length(instructions) <= 4000),
  avatar BLOB,
  avatar_mime TEXT,
  default_model_id TEXT,
  reply_locale TEXT NOT NULL CHECK(reply_locale IN ('zh-TW', 'en')),
  config_revision INTEGER NOT NULL,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  CHECK((avatar IS NULL AND avatar_mime IS NULL) OR
    (avatar IS NOT NULL AND length(avatar) BETWEEN 1 AND 92160 AND
      (avatar_mime IS 'image/png' OR avatar_mime IS 'image/jpeg'))),
  CHECK(
    (id = 'main' AND role = 'orchestrator' AND builtin_key IS 'main' AND state = 'active') OR
    (id = 'bi' AND role = 'specialist' AND builtin_key IS 'bi' AND state = 'active') OR
    (id NOT IN ('main', 'bi') AND role = 'specialist' AND builtin_key IS NULL)
  )
) STRICT;
CREATE UNIQUE INDEX agents_single_orchestrator ON agents(role) WHERE role = 'orchestrator';
CREATE TRIGGER agents_keep_builtin BEFORE DELETE ON agents
WHEN OLD.builtin_key IS NOT NULL
BEGIN
  SELECT RAISE(ABORT, 'Built-in agents cannot be deleted');
END;
CREATE TRIGGER agents_fix_builtin_identity BEFORE UPDATE OF id, role, builtin_key ON agents
WHEN (OLD.builtin_key IS NOT NULL OR NEW.builtin_key IS NOT NULL) AND
  (OLD.id IS NOT NEW.id OR OLD.role IS NOT NEW.role OR OLD.builtin_key IS NOT NEW.builtin_key)
BEGIN
  SELECT RAISE(ABORT, 'Built-in agent identity is fixed');
END;
CREATE TRIGGER agents_keep_builtin_on_insert BEFORE INSERT ON agents
WHEN NEW.id IN ('main', 'bi') AND EXISTS (SELECT 1 FROM agents WHERE id = NEW.id)
BEGIN
  SELECT RAISE(ABORT, 'Built-in agents cannot be replaced');
END;
CREATE TABLE agent_workspaces (
  id TEXT PRIMARY KEY,
  agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  layout TEXT NOT NULL CHECK(layout IN ('managed', 'legacy_default', 'legacy_secondary')),
  relative_root TEXT NOT NULL UNIQUE,
  display_name TEXT,
  is_default INTEGER NOT NULL CHECK(is_default IN (0, 1)),
  classification TEXT NOT NULL DEFAULT 'unclassified' CHECK(classification IN ('unclassified', 'public', 'confidential')),
  created_at INTEGER NOT NULL,
  UNIQUE(id, agent_id)
) STRICT;
CREATE UNIQUE INDEX agent_workspaces_one_default ON agent_workspaces(agent_id) WHERE is_default = 1;
CREATE TABLE workspace_read_folders (
  workspace_id TEXT NOT NULL REFERENCES agent_workspaces(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  folder TEXT NOT NULL,
  PRIMARY KEY(workspace_id, folder)
) STRICT;
CREATE TABLE agent_knowledge_reads (
  agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  vault_id TEXT NOT NULL,
  PRIMARY KEY(agent_id, vault_id)
) STRICT;
CREATE TABLE agent_write_targets (
  agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  target_kind TEXT NOT NULL CHECK(target_kind IN ('knowledge', 'bi_intake', 'collection')),
  target_id TEXT NOT NULL,
  write_mode TEXT NOT NULL CHECK(write_mode = 'proposal_only'),
  PRIMARY KEY(agent_id, target_kind, target_id)
) STRICT;
CREATE TABLE agent_capabilities (
  agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  kind TEXT NOT NULL CHECK(kind IN ('skill', 'workflow', 'mcp', 'plugin')),
  capability_id TEXT NOT NULL,
  enabled INTEGER NOT NULL CHECK(enabled IN (0, 1)),
  PRIMARY KEY(agent_id, kind, capability_id)
) STRICT;
CREATE TABLE workspace_mcp_grants (
  workspace_id TEXT NOT NULL REFERENCES agent_workspaces(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  server_id TEXT NOT NULL REFERENCES mcp_servers(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  PRIMARY KEY(workspace_id, server_id)
) STRICT;
CREATE TABLE agent_trigger_settings (
  agent_id TEXT PRIMARY KEY REFERENCES agents(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  message_enabled INTEGER NOT NULL CHECK(message_enabled IN (0, 1))
) STRICT;
CREATE TABLE file_classifications (
  file_kind TEXT NOT NULL CHECK(file_kind IN ('attachment', 'artifact', 'handoff', 'workspace')),
  file_id TEXT NOT NULL,
  workspace_id TEXT NOT NULL REFERENCES agent_workspaces(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  sha256 TEXT NOT NULL,
  classification TEXT NOT NULL DEFAULT 'unclassified' CHECK(classification IN ('unclassified', 'public', 'confidential')),
  updated_at INTEGER NOT NULL,
  PRIMARY KEY(file_kind, file_id, workspace_id, sha256)
) STRICT;
CREATE TABLE delegation_budget_settings (
  id INTEGER PRIMARY KEY CHECK(id = 1),
  delegations_per_message INTEGER NOT NULL DEFAULT 3 CHECK(delegations_per_message > 0),
  execution_ms_per_delegation INTEGER NOT NULL DEFAULT 300000 CHECK(execution_ms_per_delegation > 0),
  model_requests_per_delegation INTEGER NOT NULL DEFAULT 10 CHECK(model_requests_per_delegation > 0),
  tool_calls_per_delegation INTEGER NOT NULL DEFAULT 30 CHECK(tool_calls_per_delegation > 0),
  model_requests_per_message INTEGER NOT NULL DEFAULT 30 CHECK(model_requests_per_message > 0),
  tool_calls_per_message INTEGER NOT NULL DEFAULT 90 CHECK(tool_calls_per_message > 0),
  queue_ms INTEGER NOT NULL DEFAULT 600000 CHECK(queue_ms > 0)
) STRICT;
CREATE TABLE session_ownership (
    session_id TEXT PRIMARY KEY REFERENCES web_sessions(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    agent_id TEXT NOT NULL,
    workspace_id TEXT NOT NULL,
    origin TEXT NOT NULL CHECK(origin IN ('web', 'channel', 'delegation', 'schedule')),
    channel_account_id TEXT,
    conversation_key TEXT,
    binding_revision INTEGER,
    CHECK((origin = 'channel' AND channel_account_id IS NOT NULL AND conversation_key IS NOT NULL AND binding_revision IS NOT NULL) OR
      (origin <> 'channel' AND channel_account_id IS NULL AND conversation_key IS NULL AND binding_revision IS NULL))
    , FOREIGN KEY(workspace_id, agent_id) REFERENCES agent_workspaces(id, agent_id) ON DELETE RESTRICT ON UPDATE RESTRICT
  ) STRICT;
CREATE INDEX session_ownership_by_agent_origin ON session_ownership(agent_id, origin, session_id);
CREATE TRIGGER agents_archive_without_open_runs BEFORE UPDATE OF state ON agents
    WHEN OLD.state = 'active' AND NEW.state = 'archived' AND OLD.builtin_key IS NULL AND EXISTS (
      SELECT 1 FROM session_ownership o JOIN web_turns t ON t.session_id = o.session_id
      JOIN runs r ON r.id = t.run_id WHERE o.agent_id = OLD.id AND r.state NOT IN ('verified', 'failed', 'cancelled')
    ) BEGIN
      SELECT RAISE(ABORT, 'An agent with open runs cannot be archived');
    END;
CREATE TABLE channel_accounts (
    id TEXT PRIMARY KEY, provider TEXT NOT NULL,
    account_fingerprint TEXT CHECK(length(account_fingerprint)=64 AND account_fingerprint NOT GLOB '*[^0-9a-f]*'),
    credential_ref TEXT NOT NULL UNIQUE, allowlist_ref TEXT NOT NULL,
    agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
    handler TEXT NOT NULL CHECK(handler IN ('chat','bi_intake')),
    state TEXT NOT NULL CHECK(state IN ('unverified','enabled','disabled')),
    binding_revision INTEGER NOT NULL CHECK(binding_revision > 0),
    created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL,
    UNIQUE(provider,account_fingerprint),
    CHECK(state <> 'enabled' OR account_fingerprint IS NOT NULL),
    CHECK(handler <> 'bi_intake' OR agent_id='bi')
  ) STRICT;
CREATE TRIGGER agents_archive_without_enabled_channels BEFORE UPDATE OF state ON agents
    WHEN OLD.state='active' AND NEW.state='archived' AND EXISTS (
      SELECT 1 FROM channel_accounts WHERE agent_id=OLD.id AND state='enabled'
    ) BEGIN SELECT RAISE(ABORT,'An agent with enabled channels cannot be archived'); END;
CREATE TABLE agent_work_items (
  id TEXT PRIMARY KEY,
  agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT ON UPDATE RESTRICT,
  source TEXT NOT NULL CHECK(source IN ('direct', 'delegation', 'schedule')),
  source_key TEXT NOT NULL,
  effect_class TEXT NOT NULL CHECK(effect_class IN ('write', 'verified_read')),
  state TEXT NOT NULL CHECK(state IN ('queued', 'running', 'succeeded', 'failed', 'cancelled', 'indeterminate', 'timed_out')),
  enqueued_at INTEGER NOT NULL,
  ready_at INTEGER NOT NULL,
  expires_at INTEGER,
  lease_id TEXT,
  lease_until INTEGER,
  run_store TEXT CHECK(run_store IN ('web', 'channel')),
  run_id TEXT,
  schedule_ref TEXT,
  payload TEXT NOT NULL CHECK(json_valid(payload)),
  reason_code TEXT,
  UNIQUE(source, source_key),
  CHECK((state IN ('running', 'indeterminate')) = (lease_id IS NOT NULL)),
  CHECK((lease_id IS NULL) = (lease_until IS NULL)),
  CHECK((run_store IS NULL) = (run_id IS NULL))
) STRICT;
CREATE INDEX agent_work_items_pending ON agent_work_items(agent_id, state, ready_at, enqueued_at, id);
CREATE UNIQUE INDEX agent_work_items_write_lease ON agent_work_items(agent_id)
  WHERE effect_class = 'write' AND lease_id IS NOT NULL;
CREATE TABLE delegations (
  id TEXT PRIMARY KEY,
  work_id TEXT NOT NULL UNIQUE REFERENCES agent_work_items(id),
  parent_store TEXT NOT NULL CHECK(parent_store IN ('web', 'channel')),
  parent_session_id TEXT NOT NULL,
  parent_run_id TEXT NOT NULL,
  target_agent_id TEXT NOT NULL REFERENCES agents(id) CHECK(target_agent_id <> 'main'),
  child_session_id TEXT REFERENCES web_sessions(id),
  child_run_id TEXT UNIQUE REFERENCES runs(id),
  request_key TEXT NOT NULL CHECK(length(request_key) BETWEEN 1 AND 64),
  request_hash TEXT NOT NULL CHECK(length(request_hash) = 64 AND request_hash NOT GLOB '*[^0-9a-f]*'),
  status TEXT NOT NULL CHECK(status IN ('queued', 'running', 'succeeded', 'needs_input', 'failed', 'timed_out', 'cancelled', 'indeterminate')),
  reserved_requests INTEGER NOT NULL CHECK(reserved_requests >= 0),
  reserved_tools INTEGER NOT NULL CHECK(reserved_tools >= 0),
  reserved_ms INTEGER NOT NULL CHECK(reserved_ms >= 0),
  used_requests INTEGER NOT NULL DEFAULT 0 CHECK(used_requests >= 0),
  used_tools INTEGER NOT NULL DEFAULT 0 CHECK(used_tools >= 0),
  elapsed_ms INTEGER NOT NULL DEFAULT 0 CHECK(elapsed_ms >= 0),
  created_at INTEGER NOT NULL,
  finished_at INTEGER,
  result TEXT CHECK(result IS NULL OR json_valid(result)),
  destination TEXT NOT NULL CHECK(json_valid(destination)),
  UNIQUE(parent_store, parent_run_id, request_key),
  UNIQUE(parent_store, parent_run_id, request_hash),
  UNIQUE(parent_store, parent_run_id, id),
  CHECK(child_run_id IS NULL OR child_session_id IS NOT NULL),
  CHECK((status IN ('queued', 'running') AND finished_at IS NULL AND result IS NULL) OR
    (status NOT IN ('queued', 'running') AND finished_at IS NOT NULL AND result IS NOT NULL))
) STRICT;
CREATE INDEX delegations_parent_session ON delegations(parent_store, parent_session_id, created_at);
CREATE TABLE delegation_events (
  delegation_id TEXT NOT NULL REFERENCES delegations(id),
  sequence INTEGER NOT NULL CHECK(sequence > 0),
  at INTEGER NOT NULL,
  state TEXT NOT NULL,
  reason_code TEXT,
  metrics TEXT CHECK(metrics IS NULL OR json_valid(metrics)),
  PRIMARY KEY(delegation_id, sequence)
) STRICT;
CREATE TABLE delegation_request_keys (
  parent_store TEXT NOT NULL CHECK(parent_store IN ('web', 'channel')),
  parent_run_id TEXT NOT NULL,
  request_key TEXT NOT NULL CHECK(length(request_key) BETWEEN 1 AND 64),
  delegation_id TEXT NOT NULL,
  PRIMARY KEY(parent_store, parent_run_id, request_key),
  FOREIGN KEY(parent_store, parent_run_id, delegation_id) REFERENCES delegations(parent_store, parent_run_id, id)
) STRICT;
CREATE TABLE delegation_files (
  delegation_id TEXT NOT NULL REFERENCES delegations(id),
  file_id TEXT NOT NULL,
  direction TEXT NOT NULL CHECK(direction IN ('inbound', 'outbound')),
  source_file_id TEXT NOT NULL,
  name TEXT NOT NULL,
  bytes INTEGER NOT NULL CHECK(bytes BETWEEN 0 AND 41943040),
  sha256 TEXT NOT NULL CHECK(length(sha256) = 64 AND sha256 NOT GLOB '*[^0-9a-f]*'),
  classification TEXT NOT NULL CHECK(classification IN ('unclassified', 'public', 'confidential')),
  provenance TEXT NOT NULL CHECK(json_valid(provenance)),
  PRIMARY KEY(delegation_id, file_id)
) STRICT;
CREATE TABLE delegation_notices (
  delegation_id TEXT NOT NULL REFERENCES delegations(id),
  kind TEXT NOT NULL,
  state TEXT NOT NULL,
  effect_key TEXT NOT NULL UNIQUE,
  created_at INTEGER NOT NULL,
  seen_at INTEGER,
  PRIMARY KEY(delegation_id, kind)
) STRICT;
CREATE TABLE external_helper_settings (
  provider TEXT PRIMARY KEY CHECK(provider IN ('claude_code','codex_cli')),
  enabled INTEGER NOT NULL CHECK(enabled IN (0,1)),
  confirm_each_run INTEGER NOT NULL CHECK(confirm_each_run IN (0,1)),
  terms_confirmed INTEGER NOT NULL CHECK(terms_confirmed IN (0,1)),
  revision INTEGER NOT NULL CHECK(revision > 0),
  CHECK(provider <> 'claude_code' OR enabled = 0 OR terms_confirmed = 1),
  CHECK(provider = 'claude_code' OR terms_confirmed = 0)
) STRICT;
CREATE TABLE external_sources (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL REFERENCES web_sessions(id),
  workspace_id TEXT NOT NULL REFERENCES agent_workspaces(id),
  kind TEXT NOT NULL CHECK(kind IN ('attachment','workspace','owner_text','derived','citation')),
  descriptor TEXT NOT NULL CHECK(json_valid(descriptor)),
  UNIQUE(session_id,kind,descriptor)
) STRICT;
CREATE TABLE external_snapshots (
  id TEXT PRIMARY KEY,
  session_id TEXT NOT NULL REFERENCES web_sessions(id),
  parent_run_id TEXT NOT NULL,
  provider TEXT NOT NULL CHECK(provider IN ('claude_code','codex_cli')),
  settings_revision INTEGER NOT NULL CHECK(settings_revision > 0),
  digest TEXT NOT NULL CHECK(length(digest) = 64),
  manifest TEXT NOT NULL CHECK(json_valid(manifest)),
  content BLOB NOT NULL CHECK(length(content) BETWEEN 1 AND 41943040),
  created_at INTEGER NOT NULL
) STRICT;
CREATE INDEX external_snapshots_parent ON external_snapshots(session_id,parent_run_id);
CREATE TABLE external_confirmations (
  delegation_id TEXT PRIMARY KEY REFERENCES delegations(id),
  snapshot_id TEXT NOT NULL REFERENCES external_snapshots(id),
  expires_at INTEGER NOT NULL,
  challenge TEXT NOT NULL UNIQUE CHECK(length(challenge) = 36),
  decision TEXT CHECK(decision IN ('confirmed','owner_selection')),
  decided_at INTEGER,
  CHECK((decision IS NULL) = (decided_at IS NULL))
) STRICT;
CREATE TABLE telegram_account_settings (
  account_id TEXT PRIMARY KEY REFERENCES channel_accounts(id),
  bot_name TEXT,
  removed INTEGER NOT NULL DEFAULT 0 CHECK(removed IN (0,1))
) STRICT;
CREATE TABLE delegation_budget_choice (
  id INTEGER PRIMARY KEY CHECK(id=1),
  choice TEXT NOT NULL CHECK(choice IN ('lean','standard','relaxed','custom'))
) STRICT;
